-- Reset production data and seed the global claimant-firm templates.
-- Schema is unchanged. site_url and cron_secret stay in app_private.system_config.
-- Starter DOCX files and the app admin are applied by scripts/seed-production.ts.
-- The admin password is supplied in APP_ADMIN_PASSWORD and is not stored here.

DO $$
DECLARE
  tables text;
BEGIN
  SELECT string_agg(format('%I.%I', schemaname, tablename), ', ' ORDER BY tablename)
  INTO tables
  FROM pg_tables
  WHERE schemaname = 'public';

  IF tables IS NOT NULL THEN
    EXECUTE 'TRUNCATE TABLE ' || tables || ' RESTART IDENTITY CASCADE';
  END IF;
END $$;

DELETE FROM storage.objects;

DELETE FROM auth.users;

DELETE FROM app_private.system_config
WHERE key IN (
  'case_analysis_prompt',
  'default_chat_system_prompt',
  'default_formalize_system_prompt'
);

