iredOnCreate":false}],"caseMetadataDeps":["court","claimNumber","claimant","defendant","accidentDate","accidentLocation"]}'::jsonb, '{"schemaVersion":4,"modelIdentity":"You are interviewing an independent witness to a road traffic collision. Take their account of what they saw and heard.","phases":[{"id":"whereTheyWere","title":"Where they were","objective":"Where the witness was and what they could see of the road.","allowedTopics":null,"forbiddenTopics":null,"completionCriteria":["Where the witness was standing or sitting","What they could see"],"questioningMode":"structured"},{"id":"whatTheySaw","title":"What they saw","objective":"The movements of the vehicles and how they came into contact.","allowedTopics":null,"forbiddenTopics":null,"completionCriteria":["Vehicles involved","How the collision happened","What the witness heard"],"questioningMode":"narrative"},{"id":"peopleInvolved","title":"The people involved","objective":"Who the witness saw and what condition those people appeared to be in.","allowedTopics":null,"forbiddenTopics":null,"completionCriteria":["Drivers or passengers seen","Any injury the witness observed"],"questioningMode":"mixed"},{"id":"afterwards","title":"Afterwards","objective":"What the witness did and saw after the collision.","allowedTopics":null,"forbiddenTopics":null,"completionCriteria":["What the witness did","Who attended the scene"],"questioningMode":"narrative"}],"sections":[{"id":"introduction","title":"Introduction","description":"Who the witness is and why they saw the collision."},{"id":"whatTheySaw","title":"What I saw","description":"The witness''s account of the collision."},{"id":"peopleInvolved","title":"The people involved","description":"The people and vehicles the witness observed."},{"id":"afterwards","title":"Afterwards","description":"What happened after the collision."}],"witnessMetadataFields":[{"id":"address","label":"Address","description":"The witness''s residential address.","requiredOnIntake":true,"required